/*
 * A107163  Primes of the form 7x^2 + 8y^2.
 * https://oeis.org/A107163
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   the sequence is generated by collecting all primes p that can be
 *            written in the form 7*x^2 + 8*y^2 for non‑negative integers x,
 *            y, and listing them in increasing order. The function builds a
 *            prime sieve up to a fixed bound and extracts the required primes
 *            once; subsequent calls use the stored table
 * Range:     u8 none, u16 none, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

/* ------------------------------------------------------------ */
/* Parameters */

/* The sieve is built up to this value.  It is large enough for the
   first 10 000 terms of the sequence. */
#define SIEVE_BOUND 20000000ULL   /* 20 million */

/* ------------------------------------------------------------ */
/* Static storage */

static unsigned char sieve[SIEVE_BOUND + 1] = {0};
static unsigned char used[SIEVE_BOUND + 1] = {0};
static seq_t *prime_vec = NULL;    /* array of primes of the form */
static idx_t prime_vec_len = 0;    /* current number of stored primes */
static idx_t prime_vec_cap = 0;    /* allocation capacity */
static bool initialized = false;   /* have we built the table? */

/* ------------------------------------------------------------ */
/* Helper: comparison for qsort */

static int cmp_seq(const void *a, const void *b)
{
    const seq_t *va = (const seq_t *)a;
    const seq_t *vb = (const seq_t *)b;
    if (*va < *vb) return -1;
    if (*va > *vb) return 1;
    return 0;
}

/* ------------------------------------------------------------ */
/* Helper: append a prime to the vector */

static void add_prime_vec(seq_t p)
{
    if (prime_vec_cap == 0) {
        prime_vec_cap = 128;
        prime_vec = (seq_t *)malloc(prime_vec_cap * sizeof(seq_t));
    } else if (prime_vec_len == prime_vec_cap) {
        prime_vec_cap <<= 1;
        prime_vec = (seq_t *)realloc(prime_vec, prime_vec_cap * sizeof(seq_t));
    }
    prime_vec[prime_vec_len++] = p;
}

/* ------------------------------------------------------------ */
/* Initialize the sieve and collect the required primes */

static void init_sequence(void)
{
    if (initialized) return;
    initialized = true;

    /* ----- Eratosthenes sieve ----- */
    memset(sieve, 1, sizeof(sieve));
    sieve[0] = sieve[1] = 0;
    for (idx_t i = 2; (i * i) <= SIEVE_BOUND; ++i) {
        if (sieve[i]) {
            for (idx_t j = i * i; j <= SIEVE_BOUND; j += i)
                sieve[j] = 0;
        }
    }

    /* ----- Gather primes of the form 7*x^2 + 8*y^2 ----- */
    for (idx_t x = 1; ; ++x) {
        seq_t xsq = (seq_t)7 * ((seq_t)x * (seq_t)x);
        if (xsq > SIEVE_BOUND) break;
        for (idx_t y = 0; ; ++y) {
            seq_t ysq = (seq_t)8 * ((seq_t)y * (seq_t)y);
            seq_t p   = xsq + ysq;
            if (p > SIEVE_BOUND) break;
            if (p >= 2 && sieve[(idx_t)p] && !used[(idx_t)p]) {
                used[(idx_t)p] = 1;
                add_prime_vec(p);
            }
        }
    }

    /* ----- Sort the resulting list to ensure ascending order ----- */
    qsort(prime_vec, prime_vec_len, sizeof(seq_t), cmp_seq);

    /* ----- Remove any accidental duplicates (should not occur) ----- */
    idx_t uniq = 0;
    for (idx_t i = 0; i < prime_vec_len; ++i) {
        if (uniq == 0 || prime_vec[i] != prime_vec[uniq - 1])
            prime_vec[uniq++] = prime_vec[i];
    }
    prime_vec_len = uniq;
}

/* ------------------------------------------------------------ */
/* Public sequence function */

seq_t a(idx_t n)
{
    if (n == 0)          /* offset is 1; undefined behaviour below */
        return 0;
    init_sequence();
    if (n - 1 < prime_vec_len)
        return prime_vec[n - 1];
    /* If we have not pre‑computed that many terms, return 0.  The
       sequence can be extended by increasing SIEVE_BOUND. */
    return 0;
}
